<?php
/**
 * جدول‌های افزایشی فاز دوم. هر بسته جدول خودش را این‌جا اضافه می‌کند تا همهٔ تغییرات فاز دوم یک‌جا دیده شود.
 * هیچ جدول مالی یا انباری قبلی تکثیر یا بازنویسی نمی‌شود.
 */
namespace Agah\Erp\Core;
if(!defined('ABSPATH'))exit;
final class Phase2Schema {
    /** جدول‌های استاندارد شرکتی (با company_id و کلید خارجی به شرکت). */
    private static function standard(){return ['ratio_snapshots','import_batches','import_rows','posting_rules','posting_memory','asset_categories','asset_places','asset_custody','org_units','org_posts','post_assignments','pay_items','payroll_tariffs','payroll_runs','payroll_run_lines','payroll_run_adjustments','price_policies','price_overrides','referrals','referral_events','share_links','user_shortcuts','subscriptions','sub_events','notifications','import_map','connect_refunds','moadian_policies','moadian_records'];}
    public static function tables(){return array_merge(self::standard(),['company_purges','company_archive_chunks','sub_plans','sub_prices','sub_festival_slots','message_queue']);}
    public static function ddl($p,$c){
        $defs=[
            // نتیجهٔ ثابت نسبت‌های مالی یک دوره، برای مقایسه و حسابرسی؛ قابل حذف.
            'ratio_snapshots'=>"date_from date NOT NULL,\n  date_to date NOT NULL,\n  payload longtext NOT NULL,\n  created_by bigint(20) unsigned NOT NULL,\n  KEY company_period (company_id,date_to),",
            // دستهٔ ورود Excel (سند یا صورتحساب بانک). فایل خام نگه داشته نمی‌شود؛ فقط اثر انگشت و ردیف‌های خوانده‌شده.
            'import_batches'=>"kind varchar(10) NOT NULL,\n  file_name varchar(190) NOT NULL,\n  file_sha256 char(64) NOT NULL,\n  treasury_account_id bigint(20) unsigned DEFAULT NULL,\n  unit varchar(8) NOT NULL DEFAULT 'rial',\n  headers longtext NOT NULL,\n  mapping text NOT NULL,\n  status varchar(12) NOT NULL DEFAULT 'preview',\n  rows_total int(10) unsigned NOT NULL DEFAULT 0,\n  rows_error int(10) unsigned NOT NULL DEFAULT 0,\n  snapshot char(64) NOT NULL DEFAULT '',\n  adapter varchar(20) NOT NULL DEFAULT 'xlsx-v1',\n  encoding varchar(16) NOT NULL DEFAULT '',\n  source_system varchar(40) NOT NULL DEFAULT '',\n  mapping_version int(10) unsigned NOT NULL DEFAULT 1,\n  options text NULL,\n  created_by bigint(20) unsigned NOT NULL,\n  posted_by bigint(20) unsigned NOT NULL DEFAULT 0,\n  posted_at datetime DEFAULT NULL,\n  KEY company_file (company_id,kind,file_sha256),\n  KEY company_status (company_id,kind,status),",
            // ردیف خوانده‌شده و تصمیم آن. پیوند به سند/ردیف سند عمداً کلید خارجی ندارد تا حذف پیش‌نویس سند مسدود نشود؛ هنگام نمایش بررسی می‌شود.
            'import_rows'=>"batch_id bigint(20) unsigned NOT NULL,\n  row_no int(10) unsigned NOT NULL,\n  raw longtext NOT NULL,\n  status varchar(12) NOT NULL,\n  error varchar(500) NOT NULL DEFAULT '',\n  group_key varchar(40) NOT NULL DEFAULT '',\n  treasury_account_id bigint(20) unsigned DEFAULT NULL,\n  txn_date date DEFAULT NULL,\n  direction varchar(3) NOT NULL DEFAULT '',\n  amount bigint(20) unsigned NOT NULL DEFAULT 0,\n  reference varchar(80) NOT NULL DEFAULT '',\n  description varchar(500) NOT NULL DEFAULT '',\n  data longtext NULL,\n  match_line_id bigint(20) unsigned DEFAULT NULL,\n  voucher_id bigint(20) unsigned DEFAULT NULL,\n  treasury_doc_id bigint(20) unsigned DEFAULT NULL,\n  decision varchar(12) NOT NULL DEFAULT '',\n  rule_id bigint(20) unsigned DEFAULT NULL,\n  decided_by bigint(20) unsigned NOT NULL DEFAULT 0,\n  decided_at datetime DEFAULT NULL,\n  KEY batch_row (company_id,batch_id,row_no),\n  KEY match_line (company_id,match_line_id),\n  KEY bank_dup (company_id,treasury_account_id,txn_date,amount),",
            // قاعدهٔ نسخه‌دار: ویرایش، نسخهٔ تازه می‌سازد و نسخهٔ قبلی برای ردپای تصمیم‌ها می‌ماند.
            'posting_rules'=>"name varchar(100) NOT NULL,\n  contains_text varchar(100) NOT NULL,\n  direction varchar(3) NOT NULL DEFAULT 'any',\n  account_id bigint(20) unsigned NOT NULL,\n  detail_id bigint(20) unsigned DEFAULT NULL,\n  priority int(10) NOT NULL DEFAULT 100,\n  version int(10) unsigned NOT NULL DEFAULT 1,\n  root_id bigint(20) unsigned NOT NULL DEFAULT 0,\n  is_active tinyint(1) NOT NULL DEFAULT 1,\n  created_by bigint(20) unsigned NOT NULL,\n  KEY company_active (company_id,is_active,priority),",
            // حافظهٔ یادگیری: اثر انگشت شرح تراکنش => حسابی که انسان انتخاب کرد.
            'posting_memory'=>"fingerprint char(64) NOT NULL,\n  sample varchar(200) NOT NULL,\n  direction varchar(3) NOT NULL,\n  account_id bigint(20) unsigned NOT NULL,\n  detail_id bigint(20) unsigned DEFAULT NULL,\n  hits int(10) unsigned NOT NULL DEFAULT 1,\n  last_used_at datetime NOT NULL,\n  UNIQUE KEY company_fp (company_id,fingerprint,direction),",
            // دستهٔ دارایی و واحد/محل نگهداری؛ رکورد مجزا با شناسهٔ پایدار.
            'asset_categories'=>"code varchar(30) NOT NULL,\n  name varchar(190) NOT NULL,\n  is_active tinyint(1) NOT NULL DEFAULT 1,\n  UNIQUE KEY company_code (company_id,code),",
            'asset_places'=>"kind varchar(10) NOT NULL,\n  code varchar(30) NOT NULL,\n  name varchar(190) NOT NULL,\n  is_active tinyint(1) NOT NULL DEFAULT 1,\n  UNIQUE KEY company_code (company_id,code),",
            // دورهٔ تحویل هر دارایی نزد یک متصدی. active_slot=1 فقط برای دورهٔ جاری؛ کلید یکتا دو متصدی جاری هم‌زمان را ناممکن می‌کند.
            'asset_custody'=>"asset_id bigint(20) unsigned NOT NULL,\n  holder_type varchar(10) NOT NULL,\n  holder_id bigint(20) unsigned NOT NULL,\n  holder_name varchar(190) NOT NULL,\n  effective_date date NOT NULL,\n  ended_date date DEFAULT NULL,\n  end_kind varchar(10) DEFAULT NULL,\n  status varchar(10) NOT NULL DEFAULT 'active',\n  active_slot tinyint(1) unsigned DEFAULT 1,\n  receipt_no int(10) unsigned NOT NULL,\n  delivered_by varchar(190) NOT NULL DEFAULT '',\n  received_by varchar(190) NOT NULL DEFAULT '',\n  note varchar(300) NOT NULL DEFAULT '',\n  receipt_hash char(64) NOT NULL,\n  return_receipt_no int(10) unsigned DEFAULT NULL,\n  return_received_by varchar(190) NOT NULL DEFAULT '',\n  return_hash char(64) NOT NULL DEFAULT '',\n  prev_id bigint(20) unsigned DEFAULT NULL,\n  void_reason varchar(300) NOT NULL DEFAULT '',\n  created_by bigint(20) unsigned NOT NULL,\n  UNIQUE KEY company_current (company_id,asset_id,active_slot),\n  KEY company_holder (company_id,holder_type,holder_id,status),\n  KEY company_asset (company_id,asset_id,effective_date),\n  KEY company_receipt (company_id,receipt_no),",
            // چارت سازمانی: واحد، پست و انتساب کارمند به پست با تاریخچه (یک انتساب جاری برای هر کارمند).
            'org_units'=>"code varchar(30) NOT NULL,\n  name varchar(190) NOT NULL,\n  parent_id bigint(20) unsigned DEFAULT NULL,\n  is_active tinyint(1) NOT NULL DEFAULT 1,\n  UNIQUE KEY company_code (company_id,code),",
            'org_posts'=>"unit_id bigint(20) unsigned NOT NULL,\n  code varchar(30) NOT NULL,\n  title varchar(190) NOT NULL,\n  supervisor_post_id bigint(20) unsigned DEFAULT NULL,\n  is_active tinyint(1) NOT NULL DEFAULT 1,\n  UNIQUE KEY company_code (company_id,code),",
            'post_assignments'=>"employee_id bigint(20) unsigned NOT NULL,\n  post_id bigint(20) unsigned NOT NULL,\n  start_date date NOT NULL,\n  end_date date DEFAULT NULL,\n  status varchar(10) NOT NULL DEFAULT 'active',\n  active_slot tinyint(1) unsigned DEFAULT 1,\n  note varchar(300) NOT NULL DEFAULT '',\n  created_by bigint(20) unsigned NOT NULL,\n  UNIQUE KEY company_current (company_id,employee_id,active_slot),\n  KEY company_post (company_id,post_id,status),",
            // اقلام مزد و کسور نسخه‌دار: هر ردیف یک نسخه با تاریخ اثر؛ نسخهٔ مؤثر بر اساس پایان ماه انتخاب می‌شود.
            'pay_items'=>"code varchar(30) NOT NULL,\n  name varchar(190) NOT NULL,\n  kind varchar(10) NOT NULL,\n  calc varchar(10) NOT NULL,\n  taxable tinyint(1) NOT NULL DEFAULT 1,\n  insurable tinyint(1) NOT NULL DEFAULT 1,\n  ceiling bigint(20) unsigned NOT NULL DEFAULT 0,\n  effective_from date NOT NULL,\n  version int(10) unsigned NOT NULL DEFAULT 1,\n  is_active tinyint(1) NOT NULL DEFAULT 1,\n  created_by bigint(20) unsigned NOT NULL,\n  UNIQUE KEY company_code_date (company_id,code,effective_from),",
            // تعرفه‌ها و سقف‌های سال (بیمه، مالیات، اضافه‌کار) با تاریخ اثر و نسخهٔ مستقل.
            'payroll_tariffs'=>"fiscal_year_id bigint(20) unsigned NOT NULL,\n  effective_from date NOT NULL,\n  version int(10) unsigned NOT NULL DEFAULT 1,\n  params_json longtext NOT NULL,\n  created_by bigint(20) unsigned NOT NULL,\n  UNIQUE KEY company_year_date (company_id,fiscal_year_id,effective_from),",
            // لیست حقوق دومرحله‌ای؛ یک لیست فعال برای هر ماه. ردیف‌ها نسخه‌دارند و نسخهٔ قفل‌شده هرگز بازنویسی نمی‌شود.
            'payroll_runs'=>"fiscal_year_id bigint(20) unsigned NOT NULL,\n  period_key char(7) NOT NULL,\n  status varchar(12) NOT NULL DEFAULT 'calculated',\n  version int(10) unsigned NOT NULL DEFAULT 1,\n  pending tinyint(1) NOT NULL DEFAULT 0,\n  sent_version int(10) unsigned NOT NULL DEFAULT 0,\n  sent_hash char(64) NOT NULL DEFAULT '',\n  doc_date date DEFAULT NULL,\n  voucher_id bigint(20) unsigned DEFAULT NULL,\n  pay_voucher_id bigint(20) unsigned DEFAULT NULL,\n  pay_account_id bigint(20) unsigned DEFAULT NULL,\n  active_slot tinyint(1) unsigned DEFAULT 1,\n  reverse_reason varchar(300) NOT NULL DEFAULT '',\n  created_by bigint(20) unsigned NOT NULL,\n  sent_by bigint(20) unsigned NOT NULL DEFAULT 0,\n  approved_by bigint(20) unsigned NOT NULL DEFAULT 0,\n  paid_by bigint(20) unsigned NOT NULL DEFAULT 0,\n  UNIQUE KEY company_period (company_id,period_key,active_slot),",
            'payroll_run_lines'=>"run_id bigint(20) unsigned NOT NULL,\n  version int(10) unsigned NOT NULL,\n  employee_id bigint(20) unsigned NOT NULL,\n  contract_id bigint(20) unsigned DEFAULT NULL,\n  attendance_id bigint(20) unsigned DEFAULT NULL,\n  status varchar(10) NOT NULL,\n  error varchar(500) NOT NULL DEFAULT '',\n  gross bigint(20) unsigned NOT NULL DEFAULT 0,\n  insurance_employee bigint(20) unsigned NOT NULL DEFAULT 0,\n  insurance_employer bigint(20) unsigned NOT NULL DEFAULT 0,\n  tax bigint(20) unsigned NOT NULL DEFAULT 0,\n  deductions bigint(20) unsigned NOT NULL DEFAULT 0,\n  net bigint(20) unsigned NOT NULL DEFAULT 0,\n  calc longtext NULL,\n  UNIQUE KEY run_version_employee (company_id,run_id,version,employee_id),",
            'payroll_run_adjustments'=>"run_id bigint(20) unsigned NOT NULL,\n  employee_id bigint(20) unsigned NOT NULL,\n  tax_override bigint(20) DEFAULT NULL,\n  earning bigint(20) unsigned NOT NULL DEFAULT 0,\n  deduction bigint(20) unsigned NOT NULL DEFAULT 0,\n  reason varchar(300) NOT NULL,\n  created_by bigint(20) unsigned NOT NULL,\n  KEY run_employee (company_id,run_id,employee_id),",
            // سقف تخفیف و دامنهٔ تغییر قیمت هر نقش (درصد×۱۰۰).
            'price_policies'=>"role_id bigint(20) unsigned NOT NULL,\n  max_discount_bp int(10) unsigned NOT NULL DEFAULT 0,\n  max_price_down_bp int(10) unsigned NOT NULL DEFAULT 0,\n  max_price_up_bp int(10) unsigned NOT NULL DEFAULT 0,\n  require_reason tinyint(1) NOT NULL DEFAULT 1,\n  UNIQUE KEY company_role (company_id,role_id),",
            'price_overrides'=>"invoice_id bigint(20) unsigned NOT NULL,\n  item_id bigint(20) unsigned NOT NULL,\n  item_name varchar(190) NOT NULL,\n  catalog_price bigint(20) unsigned NOT NULL,\n  unit_price bigint(20) unsigned NOT NULL,\n  change_bp int(10) NOT NULL,\n  discount_bp int(10) unsigned NOT NULL,\n  reason varchar(300) NOT NULL DEFAULT '',\n  user_id bigint(20) unsigned NOT NULL,\n  seen_at datetime DEFAULT NULL,\n  seen_by bigint(20) unsigned NOT NULL DEFAULT 0,\n  KEY company_unseen (company_id,seen_at),",
            'referrals'=>"invoice_id bigint(20) unsigned NOT NULL,\n  from_user bigint(20) unsigned NOT NULL,\n  to_user bigint(20) unsigned NOT NULL,\n  status varchar(10) NOT NULL DEFAULT 'open',\n  note varchar(300) NOT NULL DEFAULT '',\n  last_note varchar(300) NOT NULL DEFAULT '',\n  KEY company_to (company_id,to_user,status),\n  KEY company_invoice (company_id,invoice_id),",
            'referral_events'=>"referral_id bigint(20) unsigned NOT NULL,\n  action varchar(10) NOT NULL,\n  user_id bigint(20) unsigned NOT NULL,\n  note varchar(300) NOT NULL DEFAULT '',\n  KEY company_ref (company_id,referral_id),",
            // پیوند اشتراک: فقط اثر انگشت توکن برای جست‌وجو؛ خود توکن رمزشده تا کپی دوبارهٔ پیوند ممکن باشد.
            'share_links'=>"invoice_id bigint(20) unsigned NOT NULL,\n  token_hash char(64) NOT NULL,\n  token_enc varchar(400) NOT NULL,\n  expires_at datetime NOT NULL,\n  revoked_at datetime DEFAULT NULL,\n  created_by bigint(20) unsigned NOT NULL,\n  views int(10) unsigned NOT NULL DEFAULT 0,\n  last_view_at datetime DEFAULT NULL,\n  UNIQUE KEY token_hash (token_hash),\n  KEY company_invoice (company_id,invoice_id),",
            // میانبرهای شخصی هر کاربر در هر شرکت (UX-01).
            'user_shortcuts'=>"user_id bigint(20) unsigned NOT NULL,\n  page_key varchar(30) NOT NULL,\n  sort int(10) unsigned NOT NULL DEFAULT 0,\n  UNIQUE KEY company_user_page (company_id,user_id,page_key),",
            // اشتراک هر شرکت؛ order_ref یکتا تضمین می‌کند یک پرداخت دو دوره نسازد.
            'subscriptions'=>"plan_code varchar(20) NOT NULL,\n  period varchar(6) NOT NULL,\n  modules varchar(200) NOT NULL DEFAULT '[]',\n  start_date date DEFAULT NULL,\n  end_date date DEFAULT NULL,\n  status varchar(12) NOT NULL DEFAULT 'pending',\n  amount bigint(20) unsigned NOT NULL DEFAULT 0,\n  credit bigint(20) unsigned NOT NULL DEFAULT 0,\n  price_version int(10) unsigned NOT NULL DEFAULT 0,\n  festival tinyint(1) NOT NULL DEFAULT 0,\n  festival_slot int(10) unsigned DEFAULT NULL,\n  source varchar(10) NOT NULL DEFAULT 'woo',\n  order_ref varchar(60) DEFAULT NULL,\n  replaces_id bigint(20) unsigned DEFAULT NULL,\n  created_by bigint(20) unsigned NOT NULL DEFAULT 0,\n  UNIQUE KEY order_ref (order_ref),\n  KEY company_status (company_id,status,end_date),",
            'sub_events'=>"subscription_id bigint(20) unsigned DEFAULT NULL,\n  event varchar(20) NOT NULL,\n  data longtext NULL,\n  user_id bigint(20) unsigned NOT NULL DEFAULT 0,\n  KEY company_sub (company_id,subscription_id),",
            // مرکز اعلان داخلی؛ dedupe_key از ثبت دوبارهٔ همان اعلان برای همان گیرنده جلوگیری می‌کند.
            'notifications'=>"user_id bigint(20) unsigned NOT NULL,\n  type varchar(20) NOT NULL,\n  title varchar(190) NOT NULL,\n  body varchar(500) NOT NULL DEFAULT '',\n  link varchar(300) NOT NULL DEFAULT '',\n  dedupe_key varchar(120) NOT NULL,\n  read_at datetime DEFAULT NULL,\n  UNIQUE KEY company_user_dedupe (company_id,user_id,dedupe_key),\n  KEY company_user_unread (company_id,user_id,read_at),",
            // نگاشت کد نرم‌افزار مبدأ به رکورد آگاه (IMP-02)؛ کلید یکتا ورود دوبارهٔ همان کد منبع را بی‌اثر می‌کند (IMP-03).
            'import_map'=>"source_system varchar(40) NOT NULL,\n  entity varchar(10) NOT NULL,\n  source_code varchar(60) NOT NULL,\n  source_name varchar(190) NOT NULL DEFAULT '',\n  source_parent varchar(60) NOT NULL DEFAULT '',\n  target_uuid char(36) NOT NULL,\n  target_id bigint(20) unsigned NOT NULL,\n  link varchar(10) NOT NULL DEFAULT 'created',\n  mapping_version int(10) unsigned NOT NULL DEFAULT 1,\n  batch_id bigint(20) unsigned DEFAULT NULL,\n  UNIQUE KEY company_source (company_id,source_system,entity,source_code),\n  KEY company_target (company_id,entity,target_id),",
            // استرداد وجه سفارش فروشگاه؛ استرداد پول و برگشت کالا دو رویداد جدا هستند و موجودی فقط با دریافت فیزیکی زیاد می‌شود.
            'connect_refunds'=>"client_id bigint(20) unsigned NOT NULL,\n  order_id bigint(20) unsigned NOT NULL,\n  refund_ref varchar(80) NOT NULL,\n  stage varchar(10) NOT NULL,\n  amount bigint(20) unsigned NOT NULL,\n  payload longtext NOT NULL,\n  status varchar(12) NOT NULL,\n  treasury_doc_id bigint(20) unsigned DEFAULT NULL,\n  invoice_id bigint(20) unsigned DEFAULT NULL,\n  note varchar(500) NOT NULL DEFAULT '',\n  decided_by bigint(20) unsigned NOT NULL DEFAULT 0,\n  decided_at datetime DEFAULT NULL,\n  UNIQUE KEY client_refund (client_id,refund_ref),\n  KEY company_status (company_id,status),",
            // سیاست نسخه‌دار ارسال به مؤدیان؛ هر تغییر نسخهٔ تازه است و هر ارسال نسخهٔ سیاستش را نگه می‌دارد.
            'moadian_policies'=>"version int(10) unsigned NOT NULL,\n  effective_from date NOT NULL,\n  kinds varchar(60) NOT NULL,\n  invoice_type tinyint(1) unsigned NOT NULL DEFAULT 1,\n  auto_select tinyint(1) NOT NULL DEFAULT 0,\n  note varchar(300) NOT NULL DEFAULT '',\n  created_by bigint(20) unsigned NOT NULL,\n  UNIQUE KEY company_version (company_id,version),",
            // سابقهٔ ارسال هر برگه به مؤدیان، جدا از برگه؛ شمارهٔ منحصربه‌فرد مالیاتی فقط از پاسخ رسمی یا ثبت دستی کارپوشه می‌آید.
            'moadian_records'=>"invoice_id bigint(20) unsigned NOT NULL,\n  action varchar(12) NOT NULL,\n  status varchar(12) NOT NULL,\n  policy_version int(10) unsigned NOT NULL,\n  payload longtext NULL,\n  payload_hash char(64) NOT NULL DEFAULT '',\n  errors varchar(1000) NOT NULL DEFAULT '',\n  tax_unique_id varchar(32) NOT NULL DEFAULT '',\n  reference_no varchar(64) NOT NULL DEFAULT '',\n  source varchar(10) NOT NULL DEFAULT 'queue',\n  reason varchar(300) NOT NULL DEFAULT '',\n  attempts tinyint(3) unsigned NOT NULL DEFAULT 0,\n  active_slot tinyint(1) unsigned DEFAULT 1,\n  sent_at datetime DEFAULT NULL,\n  decided_at datetime DEFAULT NULL,\n  created_by bigint(20) unsigned NOT NULL,\n  UNIQUE KEY company_active (company_id,invoice_id,active_slot),\n  KEY company_status (company_id,status),\n  KEY company_invoice (company_id,invoice_id),",
        ];
        $out=[];
        foreach($defs as $name=>$body)$out[]="CREATE TABLE {$p}{$name} (\n  id bigint(20) unsigned NOT NULL AUTO_INCREMENT,\n  uuid char(36) NOT NULL,\n  company_id bigint(20) unsigned NOT NULL,\n  $body\n  created_at datetime NOT NULL,\n  updated_at datetime NOT NULL,\n  PRIMARY KEY  (id),\n  UNIQUE KEY uuid (uuid),\n  UNIQUE KEY company_id_id (company_id,id)\n) $c;";
        // سابقهٔ پاک‌سازی شرکت؛ عمداً بدون کلید خارجی به شرکت تا پس از حذف شرکت باقی بماند. ستون شرکت target_company_id نام دارد
        // تا در فهرست «جدول‌های دارای company_id» که پاک‌سازی از آن استفاده می‌کند قرار نگیرد.
        $out[]="CREATE TABLE {$p}company_purges (\n  id bigint(20) unsigned NOT NULL AUTO_INCREMENT,\n  target_company_id bigint(20) unsigned NOT NULL,\n  company_name varchar(190) NOT NULL,\n  status varchar(12) NOT NULL,\n  stage varchar(12) NOT NULL DEFAULT '',\n  inventory longtext NOT NULL,\n  manifest longtext NULL,\n  service_users text NULL,\n  reason varchar(300) NOT NULL DEFAULT '',\n  error varchar(500) NOT NULL DEFAULT '',\n  requested_by bigint(20) unsigned NOT NULL,\n  confirmed_by bigint(20) unsigned NOT NULL DEFAULT 0,\n  archive_deleted_at datetime DEFAULT NULL,\n  created_at datetime NOT NULL,\n  updated_at datetime NOT NULL,\n  PRIMARY KEY  (id),\n  KEY target_status (target_company_id,status)\n) $c;";
        // بایگانی رمزشدهٔ رکوردهای شرکت پاک‌شده، تکه‌تکه؛ داخل پایگاه داده تا با پشتیبان سامانه همراه باشد و مسیر وب نداشته باشد.
        $out[]="CREATE TABLE {$p}company_archive_chunks (\n  id bigint(20) unsigned NOT NULL AUTO_INCREMENT,\n  purge_id bigint(20) unsigned NOT NULL,\n  table_name varchar(64) NOT NULL,\n  chunk_no int(10) unsigned NOT NULL,\n  row_count int(10) unsigned NOT NULL,\n  sha256 char(64) NOT NULL,\n  payload longtext NOT NULL,\n  PRIMARY KEY  (id),\n  UNIQUE KEY purge_chunk (purge_id,table_name,chunk_no)\n) $c;";
        // کاتالوگ طرح‌ها و قیمت‌های نسخه‌دار و ظرفیت جشنواره در سطح سامانه (نه شرکت).
        $out[]="CREATE TABLE {$p}sub_plans (\n  id bigint(20) unsigned NOT NULL AUTO_INCREMENT,\n  code varchar(20) NOT NULL,\n  name varchar(100) NOT NULL,\n  kind varchar(12) NOT NULL,\n  is_active tinyint(1) NOT NULL DEFAULT 1,\n  created_at datetime NOT NULL,\n  PRIMARY KEY  (id),\n  UNIQUE KEY code (code)\n) $c;";
        $out[]="CREATE TABLE {$p}sub_prices (\n  id bigint(20) unsigned NOT NULL AUTO_INCREMENT,\n  plan_code varchar(20) NOT NULL,\n  period varchar(6) NOT NULL,\n  amount bigint(20) unsigned NOT NULL,\n  festival_amount bigint(20) unsigned DEFAULT NULL,\n  version int(10) unsigned NOT NULL,\n  effective_from datetime NOT NULL,\n  created_by bigint(20) unsigned NOT NULL DEFAULT 0,\n  created_at datetime NOT NULL,\n  PRIMARY KEY  (id),\n  KEY plan_period (plan_code,period,effective_from)\n) $c;";
        $out[]="CREATE TABLE {$p}sub_festival_slots (\n  id bigint(20) unsigned NOT NULL AUTO_INCREMENT,\n  slot_no int(10) unsigned NOT NULL,\n  subscription_id bigint(20) unsigned NOT NULL,\n  company_ref bigint(20) unsigned NOT NULL,\n  created_at datetime NOT NULL,\n  PRIMARY KEY  (id),\n  UNIQUE KEY slot_no (slot_no),\n  UNIQUE KEY subscription_id (subscription_id)\n) $c;";
        // صف پیامک/ایمیل؛ گیرنده رمزشده و فقط بخش پوشیده‌اش قابل نمایش است.
        $out[]="CREATE TABLE {$p}message_queue (\n  id bigint(20) unsigned NOT NULL AUTO_INCREMENT,\n  company_id bigint(20) unsigned NOT NULL DEFAULT 0,\n  channel varchar(6) NOT NULL,\n  recipient_enc varchar(400) NOT NULL,\n  recipient_hint varchar(60) NOT NULL DEFAULT '',\n  subject varchar(190) NOT NULL DEFAULT '',\n  body text NOT NULL,\n  consent varchar(16) NOT NULL DEFAULT 'transactional',\n  status varchar(10) NOT NULL DEFAULT 'queued',\n  attempts tinyint(3) unsigned NOT NULL DEFAULT 0,\n  last_error varchar(300) NOT NULL DEFAULT '',\n  provider_ref varchar(100) NOT NULL DEFAULT '',\n  dedupe_key varchar(140) NOT NULL,\n  next_try_at datetime NOT NULL,\n  sent_at datetime DEFAULT NULL,\n  created_at datetime NOT NULL,\n  updated_at datetime NOT NULL,\n  PRIMARY KEY  (id),\n  UNIQUE KEY dedupe_key (dedupe_key),\n  KEY due (status,next_try_at),\n  KEY company_id (company_id)\n) $c;";
        return $out;
    }
    public static function fks(){
        $out=[];foreach(self::standard() as $t)$out[]=[$t,'fk_p2_'.$t.'_c',['company_id'],'companies',['id'],'RESTRICT'];
        $out[]=['company_archive_chunks','fk_p2_archive_purge',['purge_id'],'company_purges',['id'],'CASCADE'];
        $out[]=['import_rows','fk_p2_import_rows_batch',['company_id','batch_id'],'import_batches',['company_id','id'],'CASCADE'];
        $out[]=['import_batches','fk_p2_import_batches_treasury',['company_id','treasury_account_id'],'treasury_accounts',['company_id','id'],'RESTRICT'];
        $out[]=['asset_custody','fk_p2_asset_custody_asset',['company_id','asset_id'],'assets',['company_id','id'],'RESTRICT'];
        $out[]=['assets','fk_p2_assets_category',['company_id','category_id'],'asset_categories',['company_id','id'],'RESTRICT'];
        foreach(['org_units'=>['parent_id'=>'org_units'],'org_posts'=>['unit_id'=>'org_units','supervisor_post_id'=>'org_posts'],'post_assignments'=>['employee_id'=>'employees','post_id'=>'org_posts'],'payroll_tariffs'=>['fiscal_year_id'=>'fiscal_years'],'payroll_runs'=>['fiscal_year_id'=>'fiscal_years'],'payroll_run_lines'=>['run_id'=>'payroll_runs','employee_id'=>'employees'],'payroll_run_adjustments'=>['run_id'=>'payroll_runs','employee_id'=>'employees']] as $t=>$cols)
            foreach($cols as $col=>$parent)$out[]=[$t,'fk_p2_'.$t.'_'.$col,['company_id',$col],$parent,['company_id','id'],'RESTRICT'];
        // اثرهای جانبی برگهٔ فروش با حذف پیش‌نویس همان برگه پاک می‌شوند؛ نقش حذف‌شده سیاستش را هم می‌برد.
        foreach(['price_overrides'=>'invoice_id','referrals'=>'invoice_id','share_links'=>'invoice_id'] as $t=>$col)$out[]=[$t,'fk_p2_'.$t.'_'.$col,['company_id',$col],'invoices',['company_id','id'],'CASCADE'];
        $out[]=['price_policies','fk_p2_price_policies_role',['company_id','role_id'],'roles',['company_id','id'],'CASCADE'];
        $out[]=['referral_events','fk_p2_referral_events_ref',['company_id','referral_id'],'referrals',['company_id','id'],'CASCADE'];
        $out[]=['sub_events','fk_p2_sub_events_sub',['company_id','subscription_id'],'subscriptions',['company_id','id'],'RESTRICT'];
        foreach(['client_id'=>'connect_clients','order_id'=>'connect_orders','treasury_doc_id'=>'treasury_docs','invoice_id'=>'invoices'] as $col=>$parent)$out[]=['connect_refunds','fk_p2_connect_refunds_'.$col,['company_id',$col],$parent,['company_id','id'],'RESTRICT'];
        $out[]=['moadian_records','fk_p2_moadian_records_invoice',['company_id','invoice_id'],'invoices',['company_id','id'],'RESTRICT'];
        $out[]=['treasury_docs','fk_p2_treasury_docs_refund_of',['company_id','refund_of_doc_id'],'treasury_docs',['company_id','id'],'RESTRICT'];
        return $out;
    }
    /** مجوز «حذف شرکت» فقط به نقش مدیر شرکت داده می‌شود (نقش سفارشی خودکار گسترش نمی‌یابد). */
    public static function seed(){
        if(class_exists('Agah\\Erp\\Modules\\Subscription\\SubscriptionService'))\Agah\Erp\Modules\Subscription\SubscriptionService::seedCatalog();
        // نقش سرویس فروشگاه برای ثبت استرداد، مجوز برگهٔ پرداخت را هم لازم دارد (Schema 19).
        foreach(['payment.view','payment.create'] as $cap)Db::exec('INSERT IGNORE INTO '.Db::t('role_caps').' (role_id,cap) SELECT id,%s FROM '.Db::t('roles')." WHERE role_key='connect_store'",$cap);
        foreach(['moadian.view','moadian.edit'] as $cap)Db::exec('INSERT IGNORE INTO '.Db::t('role_caps').' (role_id,cap) SELECT id,%s FROM '.Db::t('roles')." WHERE role_key='accountant'",$cap);
        foreach(['company_settings.delete','payroll.sensitive','payroll.pay','moadian.view','moadian.edit','moadian.approve'] as $cap)Db::exec('INSERT IGNORE INTO '.Db::t('role_caps').' (role_id,cap) SELECT id,%s FROM '.Db::t('roles')." WHERE role_key='company_admin'",$cap);
    }
}
